all.css:
.pageBackground {
  overflow: hidden;
}

/* Dusk, not a darkened noon: the sky keeps its blue at the top and warms toward the horizon, which
   is what stops a dark palette reading as the light one with the lights off. Static throughout —
   PageBackground drops the glass blur for any background with keyframes. */
.aeroSky {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(to bottom, #061019 0%, #0a1b28 32%, #0f2c3d 66%, #16455a 100%);
}

/* The light is low and behind the horizon now, so the bloom sits at the bottom of the frame. */
.aeroBloom {
  position: absolute;
  inset: auto -12% -30% -12%;
  height: 78%;
  background:
    radial-gradient(52% 74% at 76% 104%, rgba(122,214,232,.34) 0%, rgba(78,168,206,.14) 34%, rgba(78,168,206,0) 70%);
  filter: blur(12px);
}

.aeroBubbles {
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 38% 32%, rgba(226,246,255,.55) 0 3%, rgba(150,214,240,.16) 30%, rgba(120,190,225,.06) 60%, rgba(120,190,225,0) 70%),
    radial-gradient(circle at 42% 30%, rgba(226,246,255,.48) 0 4%, rgba(140,206,236,.13) 30%, rgba(120,190,225,.05) 58%, rgba(120,190,225,0) 68%),
    radial-gradient(circle at 36% 34%, rgba(214,244,255,.42) 0 3%, rgba(120,200,220,.12) 28%, rgba(120,200,220,.04) 56%, rgba(120,200,220,0) 66%),
    radial-gradient(circle at 40% 30%, rgba(226,246,255,.36) 0 4%, rgba(140,206,236,.10) 28%, rgba(140,206,236,0) 64%);
  background-size: 260px 260px, 170px 170px, 120px 120px, 90px 90px;
  background-position: 12% 22%, 74% 58%, 30% 76%, 88% 14%;
  background-repeat: no-repeat;
  opacity: .7;
}

/* The horizon wash keeps the green of the light palette, pushed to teal so it sits in the dark. */
.aeroGloss {
  position: absolute;
  inset: auto 0 0 0;
  height: 44%;
  background:
    linear-gradient(to top, rgba(46,140,140,.34) 0%, rgba(60,158,164,.13) 36%, rgba(60,158,164,0) 100%),
    radial-gradient(120% 70% at 50% 118%, rgba(158,232,240,.16) 0%, rgba(158,232,240,0) 62%);
  filter: blur(8px);
}

